package com.coffeeshop.controller;import com.coffeeshop.dto.PurchasingCommands;import com.coffeeshop.model.PurchasingModels.*;import com.coffeeshop.security.ApplicationSession;import com.coffeeshop.service.PurchasingService;import javafx.application.Platform;import javafx.beans.property.SimpleStringProperty;import javafx.collections.FXCollections;import javafx.fxml.FXML;import javafx.geometry.Insets;import javafx.scene.control.*;import javafx.scene.layout.*;import java.math.BigDecimal;import java.time.*;import java.util.*;import java.util.concurrent.CompletableFuture;public final class PurchasingController{private final PurchasingService service;private final ApplicationSession session;private Catalog catalog;@FXML private TextField supplierSearch;@FXML private TableView<Supplier>supplierTable;@FXML private TableColumn<Supplier,String>supplierCodeColumn,supplierNameColumn,supplierContactColumn,supplierStatusColumn;@FXML private TableView<Purchase>purchaseTable;@FXML private TableColumn<Purchase,String>purchaseNumberColumn,purchaseSupplierColumn,purchaseDateColumn,purchaseStatusColumn,purchaseTotalColumn;@FXML private TableView<PurchaseItem>itemTable;@FXML private TableColumn<PurchaseItem,String>itemNameColumn,itemQuantityColumn,itemCostColumn,itemTotalColumn;@FXML private Label messageLabel;@FXML private Button editSupplierButton,toggleSupplierButton,editPurchaseButton,receiveButton,cancelButton;public PurchasingController(PurchasingService s,ApplicationSession a){service=Objects.requireNonNull(s);session=Objects.requireNonNull(a);}@FXML private void initialize(){supplierCodeColumn.setCellValueFactory(v->text(v.getValue().code()));supplierNameColumn.setCellValueFactory(v->text(v.getValue().name()));supplierContactColumn.setCellValueFactory(v->text(v.getValue().contact()==null?"-":v.getValue().contact()));supplierStatusColumn.setCellValueFactory(v->text(v.getValue().active()?"Active":"Inactive"));purchaseNumberColumn.setCellValueFactory(v->text(v.getValue().number()));purchaseSupplierColumn.setCellValueFactory(v->text(v.getValue().supplierName()));purchaseDateColumn.setCellValueFactory(v->text(v.getValue().purchasedAt().toLocalDate().toString()));purchaseStatusColumn.setCellValueFactory(v->text(v.getValue().status()));purchaseTotalColumn.setCellValueFactory(v->text(v.getValue().total().toPlainString()));itemNameColumn.setCellValueFactory(v->text(v.getValue().itemName()));itemQuantityColumn.setCellValueFactory(v->text(v.getValue().quantity()+" "+v.getValue().unit()));itemCostColumn.setCellValueFactory(v->text(v.getValue().unitCost().toPlainString()));itemTotalColumn.setCellValueFactory(v->text(v.getValue().total().toPlainString()));supplierSearch.textProperty().addListener((o,a,b)->filter());supplierTable.getSelectionModel().selectedItemProperty().addListener((o,a,b)->supplierSelection(b));purchaseTable.getSelectionModel().selectedItemProperty().addListener((o,a,b)->purchaseSelection(b));refresh();}@FXML private void refresh(){CompletableFuture.supplyAsync(service::catalog).whenComplete((v,e)->Platform.runLater(()->{if(e!=null){messageLabel.setText("Unable to load purchasing data.");return;}catalog=v;filter();purchaseTable.getItems().setAll(v.purchases());messageLabel.setText("");purchaseSelection(purchaseTable.getSelectionModel().getSelectedItem());}));}private void filter(){if(catalog==null)return;String q=supplierSearch.getText().trim().toLowerCase();supplierTable.getItems().setAll(catalog.suppliers().stream().filter(s->q.isEmpty()||(s.code()+" "+s.name()+" "+Objects.toString(s.contact(),"")).toLowerCase().contains(q)).toList());} @FXML private void addSupplier(){supplierDialog(null).ifPresent(this::saveSupplier);}@FXML private void editSupplier(){Supplier s=supplierTable.getSelectionModel().getSelectedItem();if(s!=null)supplierDialog(s).ifPresent(this::saveSupplier);}@FXML private void toggleSupplier(){Supplier s=supplierTable.getSelectionModel().getSelectedItem();if(s!=null)write(()->service.setSupplierActive(s,!s.active()),"Supplier updated.");}@FXML private void addPurchase(){purchaseDialog(null).ifPresent(this::savePurchase);}@FXML private void editPurchase(){Purchase p=purchaseTable.getSelectionModel().getSelectedItem();if(p!=null&&"DRAFT".equals(p.status()))purchaseDialog(p).ifPresent(this::savePurchase);}@FXML private void receive(){Purchase p=purchaseTable.getSelectionModel().getSelectedItem();if(p!=null&&confirm("Receive purchase","This will add all purchase quantities to inventory and cannot be edited afterward."))write(()->service.receive(p,user()),"Purchase received and inventory updated.");}@FXML private void cancel(){Purchase p=purchaseTable.getSelectionModel().getSelectedItem();if(p!=null&&confirm("Cancel purchase","Cancel this draft purchase?"))write(()->service.cancel(p),"Purchase cancelled.");}private void saveSupplier(PurchasingCommands.Supplier q){write(()->service.saveSupplier(q),"Supplier saved.");}private void savePurchase(PurchasingCommands.Purchase q){write(()->service.saveDraft(q,user()),"Draft purchase saved.");}private Optional<PurchasingCommands.Supplier>supplierDialog(Supplier s){Dialog<PurchasingCommands.Supplier>d=dialog(s==null?"Add supplier":"Edit supplier");TextField code=f(s==null?null:s.code()),name=f(s==null?null:s.name()),contact=f(s==null?null:s.contact()),phone=f(s==null?null:s.phone()),email=f(s==null?null:s.email()),address=f(s==null?null:s.address());TextArea notes=new TextArea(s==null||s.notes()==null?"":s.notes());notes.setPrefRowCount(2);CheckBox active=new CheckBox("Active");active.setSelected(s==null||s.active());GridPane g=form();Control[]c={code,name,contact,phone,email,address,notes};String[]n={"Code","Name","Contact person","Phone","Email","Address","Notes"};for(int i=0;i<n.length;i++)field(g,i,n[i],c[i]);g.add(active,1,7);d.getDialogPane().setContent(g);d.setResultConverter(b->b.getButtonData()==ButtonBar.ButtonData.OK_DONE?new PurchasingCommands.Supplier(s==null?null:s.id(),code.getText(),name.getText(),contact.getText(),phone.getText(),email.getText(),address.getText(),notes.getText(),active.isSelected(),s==null?null:s.version()):null);return d.showAndWait();}private Optional<PurchasingCommands.Purchase>purchaseDialog(Purchase p){Dialog<PurchasingCommands.Purchase>d=dialog(p==null?"New draft purchase":"Edit draft purchase");ComboBox<Supplier>supplier=new ComboBox<>(FXCollections.observableArrayList(catalog.suppliers().stream().filter(Supplier::active).toList()));supplier.setMaxWidth(Double.MAX_VALUE);if(p!=null)catalog.suppliers().stream().filter(x->x.id()==p.supplierId()).findFirst().ifPresent(supplier::setValue);DatePicker date=new DatePicker(p==null?LocalDate.now():p.purchasedAt().toLocalDate());TextField discount=f(p==null?"0":p.discount().toPlainString()),tax=f(p==null?"0":p.tax().toPlainString()),invoice=f(p==null?null:p.invoice());TextArea notes=new TextArea(p==null||p.notes()==null?"":p.notes());notes.setPrefRowCount(2);TableView<LineEditor>lines=new TableView<>();lines.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST_COLUMN);TableColumn<LineEditor,String>a=new TableColumn<>("Inventory item"),b=new TableColumn<>("Quantity"),c=new TableColumn<>("Unit cost");a.setCellValueFactory(v->text(v.getValue().item.toString()));b.setCellValueFactory(v->text(v.getValue().quantity.toPlainString()));c.setCellValueFactory(v->text(v.getValue().cost.toPlainString()));lines.getColumns().setAll(List.of(a,b,c));if(p!=null)for(PurchaseItem x:p.items())catalog.items().stream().filter(i->i.id()==x.itemId()).findFirst().ifPresent(i->lines.getItems().add(new LineEditor(i,x.quantity(),x.unitCost())));Button add=new Button("Add item"),remove=new Button("Remove selected");add.setOnAction(e->{ComboBox<Item>item=new ComboBox<>(FXCollections.observableArrayList(catalog.items().stream().filter(Item::active).toList()));TextField qty=f("1"),cost=f("0");GridPane q=form();field(q,0,"Inventory item",item);field(q,1,"Quantity",qty);field(q,2,"Unit cost",cost);Dialog<ButtonType>x=new Dialog<>();x.setTitle("Add purchase item");x.getDialogPane().getButtonTypes().addAll(ButtonType.CANCEL,new ButtonType("Add",ButtonBar.ButtonData.OK_DONE));x.getDialogPane().setContent(q);if(x.showAndWait().filter(z->z.getButtonData()==ButtonBar.ButtonData.OK_DONE).isPresent()&&item.getValue()!=null)try{lines.getItems().add(new LineEditor(item.getValue(),new BigDecimal(qty.getText()),new BigDecimal(cost.getText())));}catch(NumberFormatException z){messageLabel.setText("Enter valid quantity and cost values.");}});remove.setOnAction(e->lines.getItems().remove(lines.getSelectionModel().getSelectedItem()));VBox box=new VBox(8);GridPane g=form();field(g,0,"Supplier",supplier);field(g,1,"Purchase date",date);field(g,2,"Discount",discount);field(g,3,"Tax",tax);field(g,4,"Supplier invoice",invoice);field(g,5,"Notes",notes);HBox actions=new HBox(8,add,remove);lines.setPrefHeight(210);box.getChildren().addAll(g,lines,actions);d.getDialogPane().setContent(box);d.getDialogPane().setPrefWidth(650);d.setResultConverter(z->{if(z.getButtonData()!=ButtonBar.ButtonData.OK_DONE||supplier.getValue()==null)return null;try{return new PurchasingCommands.Purchase(p==null?null:p.id(),supplier.getValue().id(),date.getValue().atStartOfDay(),new BigDecimal(discount.getText()),new BigDecimal(tax.getText()),invoice.getText(),notes.getText(),lines.getItems().stream().map(x->new PurchasingCommands.Line(null,x.item.id(),x.quantity,x.cost,null)).toList(),p==null?null:p.version());}catch(NumberFormatException e){return new PurchasingCommands.Purchase(p==null?null:p.id(),supplier.getValue().id(),date.getValue().atStartOfDay(),null,null,invoice.getText(),notes.getText(),List.of(),p==null?null:p.version());}});return d.showAndWait();}private record LineEditor(Item item,BigDecimal quantity,BigDecimal cost){}private void supplierSelection(Supplier s){editSupplierButton.setDisable(s==null);toggleSupplierButton.setDisable(s==null);toggleSupplierButton.setText(s==null||s.active()?"Deactivate":"Activate");}private void purchaseSelection(Purchase p){itemTable.getItems().setAll(p==null?List.of():p.items());boolean draft=p==null||!"DRAFT".equals(p.status());editPurchaseButton.setDisable(draft);receiveButton.setDisable(draft);cancelButton.setDisable(draft);}private long user(){return session.currentUser().orElseThrow().userId();}private void write(Runnable r,String ok){CompletableFuture.runAsync(r).whenComplete((v,e)->Platform.runLater(()->{if(e==null){refresh();messageLabel.setText(ok);}else messageLabel.setText(message(e));}));}private static <T> Dialog<T> dialog(String title){Dialog<T>d=new Dialog<>();d.setTitle(title);d.getDialogPane().getButtonTypes().addAll(ButtonType.CANCEL,new ButtonType("Save",ButtonBar.ButtonData.OK_DONE));return d;}private static GridPane form(){GridPane g=new GridPane();g.setHgap(12);g.setVgap(8);g.setPadding(new Insets(8));return g;}private static void field(GridPane g,int row,String n,Control c){g.add(new Label(n),0,row);c.setMaxWidth(Double.MAX_VALUE);g.add(c,1,row);}private static TextField f(String s){return new TextField(s==null?"":s);}private static SimpleStringProperty text(String s){return new SimpleStringProperty(s);}private static boolean confirm(String t,String m){return new Alert(Alert.AlertType.CONFIRMATION,m,ButtonType.CANCEL,ButtonType.OK).showAndWait().orElse(ButtonType.CANCEL)==ButtonType.OK;}private static String message(Throwable e){Throwable x=e;while(x.getCause()!=null)x=x.getCause();return x instanceof IllegalArgumentException||x instanceof IllegalStateException?x.getMessage():"Unable to update purchasing data.";}}
